/* The prologue, "no armband" (4/6 Dark Hour to the morning of 4/8), as scene lines for femc-game.html.
   Converted from the prologue script; edit the script and re-run the converter, or edit here. Line format: scene.js. */
window.FEMC_GAME_PROLOGUE = {
  id: 'prologue', title: 'no armband',
  scene: [
    {"place": "Tartarus · First Floor", "time": "The Dark Hour", "bg": "tartarus-access-point", "music": "mystery", "date": "4/6"},
    {"cg": "prologue-waking-in-tartarus"},
    {"n": "The first thing was the cold, which came up through the floor and into her shoulder blades like the floor had been waiting a long time for someone to lie on it and meant to make the most of her."},
    {"n": "The second thing was the light, and it was wrong. It was green, a sick, soupy, aquarium green that didn't come from anywhere in particular, that just sat on everything the way fog sits on a field, and when she opened her eyes into it her first clear thought, before her name or where she was or whether anything hurt, was that she did not like being looked at by it."},
    {"n": "She sat up, slowly, because her body suggested slowly. The floor was a checkerboard of tiles that didn't quite line up, black and a green that might have been white somewhere else, and there were dark puddles on it that she decided, firmly, were water. The air smelled like old pennies and a hospital at night, clean in a way that made you think about what it was covering. Somewhere above her, very far up, something hummed, low and steady, the sound a building makes when it's alive and doesn't want you to know."},
    {"n": "She was wearing a school uniform. A black blazer, a skirt, a red ribbon at the collar, shoes that fit, tights that had a run starting at the left knee. She looked down at all of it with the polite interest of someone being shown another person's photographs."},
    {"n": "It wasn't hers. It fit like it was."},
    {"n": "She checked her pockets because her hands went to them before she told them to. Nothing. No phone, which made her stomach drop in a way that felt older than anything else she could remember, which was nothing. No keys. No wallet. No name tag, no armband, no receipt, no hair tie, not so much as a gum wrapper to say where she'd been or who had been with her. Her pockets were clean the way a hotel room is clean."},
    {"n": "Beside her right hand, on the tiles, lay a gun."},
    {"n": "It was silver, and ornate in a way guns weren't supposed to be, with a crest stamped into the grip, and it was so close to her fingers that she had the brief, insane impression it had been placed there, set down beside her by someone who had folded her hands and tucked her in and left the light on."},
    {"choose": [{"t": "(Pick it up.)", "then": [{"n": "She picked it up. It was heavier than it looked, and colder than the floor, and her hand closed around the grip and settled there the way a hand settles into a coat pocket it has been putting itself in for years. That was the part she didn't like."}]}, {"t": "(Don't touch it.)", "then": [{"n": "She didn't touch it. She sat with her hands in her lap and looked at it for a long moment, and the gun lay there and was patient. In the end she picked it up anyway, because it was the only thing in the whole green world that seemed to have been meant for her, and it was very quiet in that corridor, and she was beginning to suspect she wasn't someone who liked being unarmed."}]}]},
    {"cg": null},
    {"n": "She stood. Her knees held, which was something. The corridor ran off in both directions and bent out of sight, and the walls were patterned in a way that made her eyes slide, and she found, without deciding to, that she was counting. Two ways out. A staircase behind her going up into more green. A doorway on the left with nothing past it but dark. Three puddles. One flickering patch of light on the ceiling that wasn't a light."},
    {"n": "She didn't know why she counted. It felt like something she had done her whole life, in rooms where it mattered."},
    {"n": "At the far end of the corridor, where it bent, a girl was standing."},
    {"n": "She was small inside a navy coat that was far too big for her, the kind of heavy coat with brass buttons that somebody's uniform was supposed to fill, and the collar was turned up against her jaw and a cap was pulled low over her eyes so that all Solar could see of her face was a mouth and a chin and the faint gleam of the green on her cheek. She was holding something against her chest with both hands. A ticket, maybe. A little scrap of pink at the corner of it, a ribbon."},
    {"n": "She was looking at Solar the way you look at someone you've accidentally woken up."},
    {"s": "porter", "t": "Oh. You're awake."},
    {"s": "porter", "t": "I'm sorry. It was supposed to be quiet here."},
    {"choose": [{"t": "Where is here?", "then": [{"s": "porter", "t": "..."}, {"n": "The girl opened her mouth, and closed it, and her eyes went past Solar's shoulder to something behind her, and her whole small body went still."}]}, {"t": "Who are you?", "then": [{"s": "porter", "t": "Nobody. I'm nobody. Please don't—"}, {"n": "She stopped. Her eyes went past Solar's shoulder to something behind her, and her whole small body went still."}]}, {"t": "(Take a step toward her.)", "then": [{"n": "Solar took a step, and the girl took one back, not frightened of her, exactly, but frightened of being close, the way you'd step back from a window on a high floor. Then her eyes went past Solar's shoulder to something behind her, and her whole small body went still."}]}]},
    {"n": "Solar turned around."},
    {"n": "There were things on the floor behind her that hadn't been there a second ago, two of them, black and wet-looking and roughly the size of a large dog if a large dog had been made out of spilled ink and bad intentions. They had blue masks. That was the detail her brain chose to hold on to, out of everything. Smooth blue masks, like something from a festival, and under them a sort of gleaming suggestion of a mouth, and a great many hands that were not quite hands, flexing on the tiles."},
    {"n": "When she turned back to the end of the corridor, the girl in the coat was gone."},
    {"n": "Fuck."},
    {"battle": {"id": "prologue-1", "kind": "scripted", "script": "prologue-1", "segment": 1, "title": "Tartarus · First Floor", "desc": "Two Shadows in blue masks. Her body knows where to stand and how many ways out there are, and nothing else. Attack and Guard, until something changes.", "notes": "Tutorial fight: 2× Maya (Cowardly Maya). No Evoker command at first. Solar has only Attack and Guard, and the tutorial cards are written as her instinct (below). On turn 3, or when her HP falls below half, the Evoker command appears.", "forced": true}},
    {"n": "Her body knew things. That was the only way she could explain it later, if anyone had asked, and nobody did because nobody was there. Her body knew three things, and not one of them was how to fight."},
    {"n": "It knew where to stand. Not in front. Never in front. A little behind and to the side, where the first hit would go to something else, where she could see everything and nothing could see all of her. It had the bone-deep certainty of a habit, like she had spent a long time keeping herself alive by being the thing in the room that got hit last."},
    {"n": "It knew how many ways out there were. It knew them before she looked."},
    {"n": "And it knew, which was the most useless thing of all, how to lift her chin and keep her face perfectly still while something that wanted to hurt her looked her over. She was so good at it that for one second, against a creature with a festival mask and fifty hands, she nearly felt calm."},
    {"n": "The first one lunged. She was already somewhere else."},
    {"n": "The second one didn't miss."},
    {"n": "It hit her across the ribs like a wet rope, and the green went white at the edges, and she was on one knee with the breath knocked so far out of her she could feel the shape of where it had been. The gun was still in her hand. Her hand was shaking. The rest of her was very, very still, which felt, distantly, like something she knew about herself too: that when it really mattered she didn't shake, she got quieter, and the shaking came later, alone, with the door shut."},
    {"n": "She raised the gun at the one in front of her. She pulled the trigger. It clicked, empty and stupid, a sound like a cheap lighter."},
    {"n": "Then her hand did something she didn't ask it to."},
    {"n": "It turned the gun around, slowly, as if it had all the time in the world, and lifted it, and pressed the cold muzzle to her own right temple, and held it there. Her arm was perfectly steady now. Her heart was going so hard she could feel it in her teeth."},
    {"n": "Every part of her that was still a person screamed at her to stop. Every part of her that was something else, something underneath, something that had been waiting in the dark of her for a very long time to be asked, said *finally*."},
    {"n": "She didn't know who she was. She was almost sure she had never done this before."},
    {"n": "She squeezed."},
    {"summon": "haenim", "glitch": true, "first": true},
    {"n": "The sound of it was like every bell she'd ever heard ringing once, at the same time, in a room too small to hold them."},
    {"n": "Something rose out of the white behind her. A woman, or the shape of one, tall and slender in pink and gold that flowed like a gown and glinted like armor, with a crown of ribbons and gold pins and a veil of thin pink silk over her face, and under the veil, where her eyes should have been, a small golden sun. Her joints, where the silk fell away at the wrists, were smooth and seamed like a doll's. A white fox mask sat pushed aside on her head like a girl at a festival who'd gotten bored of it."},
    {"n": "Things hung from her sash and chimed as she moved, and Solar heard them more than saw them. A small gold bell. Something green, a ring on a red cord, that clicked against a pin shaped like a star. A pair of headphones looped at her hip, humming faintly with a song Solar could almost hear."},
    {"n": "The woman lifted one hand, and light came out of it in a long braided line, a rope of gold, and it cracked across the corridor like a whip and wrapped the nearest Shadow and pulled tight. The Shadow came apart. Not into blood. Into black ash, soft as burnt paper, drifting."},
    {"battle": {"id": "prologue-1", "kind": "scripted", "script": "prologue-1", "segment": 2, "title": "Tartarus · First Floor", "desc": "The gun works now, and something answered it. Finish the fight.", "notes": "The Evoker command now works. Haenim knows Golden Rope (Strike, may Bind) and Dia. The second Maya is weak to Light (the prologue version only); the tutorial card explains weaknesses and One More. Solar can't lose: at 1 HP the rope fires on its own.", "forced": true}},
    {"n": "The second one went the same way. Solar barely remembered telling it to."},
    {"n": "Then it was quiet. The ash settled on the tiles like snow that had given up. The woman in pink turned, slowly, and looked down at Solar through her veil, through the little sun where her eyes should have been, and Solar had the very clear and very stupid thought that she was being looked at by someone who was afraid of being looked at, and was doing it anyway."},
    {"n": "Then the woman was light, and then she was gone, and the gun was just a gun again in Solar's hand, and Solar was sitting on the floor with her back against the patterned wall, breathing like she'd run a long way to get here and only just arrived."},
    {"n": "The name was still in her head, rattling around like a coin in a dryer. She tried it in her mouth and it came apart halfway."},
    {"s": "solar", "t": "Hae... Haen—"},
    {"n": "It wouldn't hold still. It was like trying to read a word in a dream. It was hers, she was sure it was hers, and it kept sliding into other shapes, other alphabets, as if it couldn't decide which language it was supposed to be her name in."},
    {"n": "Footsteps. Fast ones, coming down the staircase she'd counted."},
    {"place": "Tartarus · First Floor", "time": "The Dark Hour", "bg": "tartarus-access-point", "music": "tender", "date": "4/6"},
    {"cg": "prologue-akihiko-finds-solar"},
    {"n": "He came around the bottom of the stairs at a run, low and light on his feet, and stopped so fast his shoes squeaked on the tile. Silver hair. A red vest over a black shirt. Boxing gloves, real ones, red, laced, and a plaster stuck above his left eyebrow like he'd come straight from losing an argument with a doorframe. He took in the ash and the gun and the girl sitting on the floor in about a second and a half, and his whole body changed, the speed going out of it and something careful coming in."},
    {"s": "akihiko", "t": "Hey. Hey, are you hurt?", "f": "surprised"},
    {"choose": [{"t": "I don't know.", "then": [{"s": "akihiko", "t": "Okay. That's okay. Don't get up yet.", "f": "serious"}]}, {"t": "Who are you?", "then": [{"s": "akihiko", "t": "Akihiko. Sanada. I'm, uh. I'm one of the people who's supposed to be here.", "f": "neutral"}, {"s": "akihiko", "t": "You're not. Which is the problem. Are you hurt?", "f": "serious"}]}, {"t": "(Look at the ash.)", "then": [{"n": "She looked at the ash instead of at him. He followed her eyes, and then looked back at her, and something in his face that had been ready for a fight sat down."}, {"s": "akihiko", "t": "...You did that.", "f": "serious"}]}]},
    {"n": "He crouched in front of her, close enough that she could see the tape around his wrists under the gloves and a small white scar running into the plaster on his eyebrow, which was a strange first thing to notice about a person, and she noticed it anyway. He smelled like cold air and a gym bag. Up close his eyes were a pale, serious gray, and they kept going to the gun in her hand and coming back to her face like he was trying to make two pieces of a puzzle that didn't belong to the same box fit together."},
    {"s": "akihiko", "t": "Where'd you get that?", "f": "serious"},
    {"s": "solar", "t": "It was on the floor. Next to me. When I woke up."},
    {"s": "akihiko", "t": "When you woke up. Here.", "f": "surprised"},
    {"s": "akihiko", "t": "That's not possible.", "f": "serious"},
    {"n": "He said it the way you'd say the sky was green, which, she thought, it was."},
    {"s": "akihiko", "t": "Those Shadows. You took them down by yourself? No backup, no training, nothing?", "f": "serious"},
    {"choose": [{"t": "I think so. It's a little blurry.", "then": [{"s": "akihiko", "t": "Ha.", "f": "happy"}, {"n": "It came out of him like he hadn't meant to let it, short and bright and delighted, a sound that didn't belong anywhere near this place."}, {"s": "akihiko", "t": "Sorry. It's not funny. It's just, I've been trying to get Mitsuru to let me come down here alone for a month, and you just... woke up and did it.", "f": "neutral"}]}, {"t": "Is that bad?", "then": [{"s": "akihiko", "t": "No. It's the opposite of bad. It's just...", "f": "serious"}, {"n": "He looked at the ash again, and then at her, and there was something in his face she would learn to recognize, later, as the look he got right before a fight he was going to enjoy."}, {"s": "akihiko", "t": "It's really something. That's all.", "f": "neutral"}]}, {"t": "There was someone else here. A girl.", "then": [{"n": "He was up and turned toward the end of the corridor before she'd finished saying it, fists up, every line of him ready. He stayed like that for a long, listening moment. Then his shoulders came down."}, {"s": "akihiko", "t": "There's nobody. I came down the only stairs on this floor. Nobody passed me.", "f": "serious"}, {"s": "akihiko", "t": "You hit your head, maybe. It's okay. This place does things to you the first time.", "f": "neutral"}, {"n": "She didn't say anything. She looked at the place where the girl in the coat had been standing, and there was nothing there but the green, sitting on everything, patient."}], "flag": {"pro-told-porter": true}}]},
    {"s": "akihiko", "t": "What's your name?", "f": "neutral"},
    {"n": "That one, at least, she knew. It came up out of her clean and whole, the only thing in her head that wasn't sliding around."},
    {"s": "solar", "t": "Solar."},
    {"s": "akihiko", "t": "Solar what?", "f": "neutral"},
    {"n": "She opened her mouth to answer, and a surname came up her throat, and then another one came up right behind it, shoving, two names with the same shape and different weights, and behind those, faint as something heard through a wall, a third. They jammed in her mouth like three people trying to get through one door. She shut her teeth on all of them."},
    {"n": "Her heart was going again. She didn't know why. They were only names."},
    {"s": "solar", "t": "...Just Solar."},
    {"n": "He looked at her for a second longer than people usually looked at you, and she braced for him to push, and he didn't."},
    {"s": "akihiko", "t": "Okay. Just Solar.", "f": "neutral"},
    {"n": "Then his eyes dropped to her sleeve, the left one, and stayed there. She looked too. There was nothing on it. Just black wool and the green light lying on it."},
    {"s": "akihiko", "t": "You're in a Gekkoukan uniform.", "f": "serious"},
    {"s": "solar", "t": "Is that what this is?"},
    {"s": "akihiko", "t": "It's mine. My school's. I'm a third-year there. I've never seen you.", "f": "serious"},
    {"n": "He said it like a fact he didn't like, and then he shook his head as if he were putting it away for later, and held out his hand. It was still in the glove. Red leather, scuffed at the knuckles, a little stiff."},
    {"s": "akihiko", "t": "Come on. You can't stay down here. Can you stand?", "f": "neutral"},
    {"n": "She took it. It was warm through the leather, warmer than anything had been since she woke up, and he pulled her up in one easy motion like she weighed nothing, and kept hold of her a second after she was steady, just long enough to check that she was, and then let go."},
    {"cg": null},
    {"n": "Something crackled near his ear. A small earpiece, half hidden by his hair."},
    {"s": "mitsuru-radio", "t": "Akihiko. Report."},
    {"s": "akihiko", "t": "First floor. I found someone.", "f": "neutral"},
    {"s": "mitsuru-radio", "t": "...Someone."},
    {"s": "akihiko", "t": "A girl. She's awake. She's not hurt. Mitsuru, she summoned.", "f": "neutral"},
    {"n": "There was a long silence on the other end, the particular silence of a very composed person setting something down very carefully so as not to throw it."},
    {"s": "mitsuru-radio", "t": "Bring her out. Now."},
    {"s": "mitsuru-radio", "t": "And then, Akihiko, you and I are going to have a conversation about the word *alone*."},
    {"s": "akihiko", "t": "...Copy.", "f": "blushing"},
    {"place": "Gekkoukan High · Front Gate", "time": "The Dark Hour", "bg": "darkhour-gekkoukan-gate", "music": "mystery", "date": "4/6"},
    {"bg": "tartarus-lobby"},
    {"n": "Getting out took longer than she expected and less time than she'd have liked, a lobby with a vast staircase and a clock that didn't tick, a set of doors, and then air, real air, cold and still, and the sky."},
    {"bg": "darkhour-gekkoukan-gate"},
    {"n": "The sky was the worst part. The moon hung over everything enormous and nearly full and the wrong color, a sick yellow-green like a bruise healing badly, and the whole city under it was lit the same, and quiet in a way cities are never quiet, no wind, no cars, no distant anything. When she turned to look back at where she'd been, there was a tower behind her so tall she had to tip her head all the way back, a twisted, impossible thing of stacked stone and spires, and it went up and up into the green until she lost it."},
    {"s": "akihiko", "t": "Tartarus. It's the school, the rest of the day. Don't ask me how. I don't think anybody actually knows.", "f": "neutral"},
    {"n": "There were coffins on the street. Upright, black, standing in a loose scatter along the sidewalk the way people stand at a crossing, waiting for a light that wasn't going to change. One was outside the gate, close enough to touch. It was about her height."},
    {"choose": [{"t": "Are those people?", "then": [{"s": "akihiko", "t": "Yeah. They're fine. They're sort of asleep. They won't remember anything. Don't touch them.", "f": "neutral"}]}, {"t": "Are they dead?", "then": [{"s": "akihiko", "t": "No. No. They're fine. It's like they're paused. It's only for an hour.", "f": "serious"}]}, {"t": "(Count them.)", "then": [{"n": "She counted them. Seven along this side of the street. Four by the bus stop. One leaning a little, like it had been checking its phone when it happened. She didn't know why she needed to know how many there were. It helped."}]}]},
    {"s": "akihiko", "t": "It's called the Dark Hour. It happens every night at midnight. Most people never know it exists.", "f": "neutral"},
    {"s": "solar", "t": "That's a stupid name."},
    {"n": "He laughed again, that same short surprised sound, like she kept reaching into him and finding it."},
    {"s": "akihiko", "t": "Yeah. It kind of is.", "f": "happy"},
    {"place": "Port Island · Convenience Store", "time": "The Dark Hour", "bg": "city", "music": "joy", "date": "4/6"},
    {"n": "They cut across Port Island toward the station, past dark shopfronts and a vending machine with no light in it, and halfway down a side street Akihiko stopped so suddenly she walked into his shoulder."},
    {"n": "There was a convenience store on the corner with its doors stuck half open and its lights dead, and somewhere inside it, quite clearly, someone was crying and also eating chips."},
    {"n": "Akihiko went in first, fists up. She went in second, with the gun held down along her leg, and noticed that she had positioned herself a step behind him and to the left without thinking about it, and noticed herself noticing, and filed it away."},
    {"n": "Behind the magazine rack, crouched with his knees up to his chin, was a boy about her age in a baseball cap and a Gekkoukan blazer, holding a family-size bag of consommé chips up in front of himself like a shield."},
    {"s": "junpei", "t": "Stay back! I know karate! I know, like, a lot of karate!", "f": "surprised"},
    {"s": "akihiko", "t": "...Iori?", "f": "surprised"},
    {"s": "junpei", "t": "Sanada-senpai?!", "f": "surprised"},
    {"s": "junpei", "t": "Oh thank god. Oh thank GOD. Senpai, everyone's in COFFINS. The guy at the register's a COFFIN. I just came in for chips, man, I was just getting chips, and the lights went green, and he turned into a—", "f": "flustered"},
    {"n": "He saw Solar. He saw the gun. His voice went up an octave and stayed there."},
    {"s": "junpei", "t": "WHY DOES SHE HAVE A GUN.", "f": "surprised"},
    {"choose": [{"t": "It's not a gun. Apparently.", "then": [{"s": "junpei", "t": "That is LITERALLY a gun!", "f": "flustered"}, {"s": "akihiko", "t": "It's... complicated.", "f": "neutral"}]}, {"t": "(Wave with the hand that isn't holding it.)", "then": [{"n": "She gave him a small, polite wave with her free hand. It was, she thought, a perfectly normal wave. Junpei looked at it like it had personally threatened his family."}]}, {"t": "Are you going to eat all of those?", "then": [{"n": "He looked down at the chips. He looked back up at her. Very slowly, with enormous suspicion and a sort of baffled respect, he held the bag out."}, {"s": "junpei", "t": "...You want some?", "f": "neutral"}, {"n": "She took one. It was very good. It was possibly the best thing she had ever eaten, which wasn't saying much, given that she couldn't remember eating anything else."}]}]},
    {"n": "And then, between one breath and the next, without any sound at all, the hour ended."},
    {"n": "The lights came on. The refrigerators woke up humming. A radio somewhere in the back was halfway through an advert for a cram school. The air moved. And behind the register, where a coffin had been a second ago, a tired man in a store apron blinked at the three of them, a boy in a heap behind the magazines, another with his fists up, and a girl in a school uniform holding a silver pistol and a chip."},
    {"s": "clerk", "t": "...Welcome?"},
    {"n": "Junpei screamed. Akihiko put a hand over his mouth. Solar, with great dignity, put the gun in her blazer pocket, where it fit perfectly, as if the pocket had been cut for it."},
    {"n": "A sleek black car was idling at the curb when they came out. Nobody had called it. Akihiko didn't look surprised."},
    {"s": "akihiko", "t": "That's Mitsuru.", "f": "neutral"},
    {"s": "akihiko", "t": "She's going to kill me.", "f": "serious"},
    {"place": "Iwatodai Dorm · Lounge", "time": "2:04 AM", "bg": "iwatodaidorm-livingroom-night", "music": "mystery", "date": "4/7"},
    {"n": "The dorm was an old brick building near the station with a lounge on the ground floor that smelled faintly of instant ramen and floor polish, deep couches arranged around a coffee table nobody had wiped in a while, a counter, a television, and the kind of tired warm lamplight that made you want to take your shoes off. Solar stood in the middle of it with her hands at her sides and was looked at."},
    {"cg": "prologue-first-night-dorm"},
    {"n": "There were three of them doing the looking. Junpei didn't count. He was in an armchair under a blanket somebody had thrown at him, eating the rest of his chips with the dazed, mechanical focus of a man who had seen God and found Him to be a convenience store."},
    {"n": "The first was a girl in pink pajama pants and a cardigan, sitting on the arm of a couch with her knees pulled up, with a brown bob that had been slept on and a face that was trying very hard to look unbothered and was mostly succeeding. There was a holster strapped over her pajamas at the thigh, which was a choice, and in it was a gun just like the one in Solar's pocket."},
    {"n": "The second was Akihiko, who had taken off the gloves and was standing by the stairs with the posture of a boy who knew he was in trouble and had decided to face it like a man."},
    {"n": "The third was the one Solar couldn't stop looking at, which was annoying, because she seemed like the kind of person who knew when she was being looked at and filed it. Red hair, long and heavy, falling in waves past her shoulders. A white blouse and a long dark skirt, fully dressed at two in the morning, sitting in the best armchair with her legs crossed at the ankle and Solar's gun resting across her open palms like something brought to her for appraisal. She hadn't said anything yet. She had a way of not saying anything that took up the whole room."},
    {"cg": null},
    {"s": "mitsuru", "t": "Please, sit down. You've had a long night.", "f": "neutral"},
    {"n": "Solar sat on the edge of the couch. Not back in it. On the edge, with her knees together and her back straight, the way you sit when you might need to stand up quickly, or when someone important is watching and you'd like them to think you were raised well. She didn't know which one this was. She suspected both."},
    {"s": "mitsuru", "t": "My name is Mitsuru Kirijo. This is Yukari Takeba. You've met Akihiko.", "f": "neutral"},
    {"s": "mitsuru", "t": "And Iori, apparently.", "f": "neutral"},
    {"s": "junpei", "t": "Hi.", "f": "flustered"},
    {"s": "yukari", "t": "Um. Hi.", "f": "neutral"},
    {"n": "Yukari's eyes went over her the way girls' eyes do, fast and thorough, uniform, hair, shoes, hands, and came back to her face and stayed there with an expression Solar couldn't read, something between suspicion and the urge to offer her a blanket too."},
    {"s": "yukari", "t": "So you just... woke up? In Tartarus? Like, *in* it?", "f": "surprised"},
    {"s": "solar", "t": "On the first floor. On the tiles."},
    {"s": "yukari", "t": "Seriously?", "f": "serious"},
    {"s": "akihiko", "t": "She took down two Shadows on her own, Mitsuru. No training. No backup. She summoned like she'd been doing it for years.", "f": "serious"},
    {"s": "mitsuru", "t": "And you were on the first floor of Tartarus, alone, at midnight, because...?", "f": "neutral"},
    {"s": "akihiko", "t": "...Training.", "f": "neutral"},
    {"s": "yukari", "t": "Oh my god.", "f": "neutral"},
    {"n": "Mitsuru turned the gun over in her hands. There was a crest on the grip, a stylized shape like an eye or a seed, and under it a small engraved number. She looked at the number for a long moment. Then she looked at Akihiko, and something passed between the two of them that was clearly a whole conversation, and then she stood, crossed to a cabinet by the counter, unlocked it with a key from her pocket, and took out a slim black case."},
    {"n": "She opened it on the coffee table. There were four foam-lined slots inside. Three were empty. The fourth held a gun identical to the one Solar had woken up next to."},
    {"n": "Mitsuru set Solar's beside it. Same silver. Same crest. Same engraving."},
    {"s": "mitsuru", "t": "We have three Evokers in use. Mine, Akihiko's, Yukari's. The fourth was ordered in March, for a new member the Chairman told me to expect.", "f": "neutral"},
    {"s": "mitsuru", "t": "Both of these are number four.", "f": "neutral"},
    {"n": "The lounge went quiet in a way that had texture. Junpei stopped chewing."},
    {"s": "junpei", "t": "Okay, so, that's a ghost thing. That's a ghost gun. I'm just saying what we're all thinking.", "f": "surprised"},
    {"s": "yukari", "t": "Junpei. Please.", "f": "serious"},
    {"s": "mitsuru", "t": "We were expecting a transfer student tonight. Third-year. The Chairman arranged it. They were meant to arrive on the last train and come here before midnight.", "f": "neutral"},
    {"s": "mitsuru", "t": "Nobody got off the train.", "f": "neutral"},
    {"choose": [{"t": "Maybe I'm them.", "then": [{"s": "mitsuru", "t": "Perhaps.", "f": "neutral"}, {"n": "She said it without warmth and without coldness, the way you'd write a figure in a ledger you meant to check twice."}]}, {"t": "I don't remember a train.", "then": [{"s": "mitsuru", "t": "No. I don't imagine you would. You didn't arrive on one.", "f": "neutral"}]}, {"t": "(Say nothing. Count the exits instead.)", "then": [{"n": "She didn't answer. She counted instead. The front door. The hall to the kitchen. The stairs. A window by the counter with an old latch that probably stuck. Four ways out. It settled something in her chest that had been standing up since the tiles."}, {"n": "When she looked back, Mitsuru was watching her eyes move, and had very clearly watched her do it, and didn't say a word about it."}]}]},
    {"s": "mitsuru", "t": "Where are you from?", "f": "neutral"},
    {"choose": [{"t": "I don't know.", "then": [{"s": "mitsuru", "t": "I see.", "f": "neutral"}]}, {"t": "Somewhere cold, I think.", "then": [{"n": "It slipped out before she could look at it. She didn't know why she'd said it. Cold air, brick, the feeling of a sleeve pulled down over your hand. It was gone before she could hold it up to the light."}, {"s": "mitsuru", "t": "...Cold. I see.", "f": "neutral"}]}, {"t": "I don't remember anything except my name. It's Solar.", "then": [{"s": "yukari", "t": "Just Solar?", "f": "surprised"}, {"s": "akihiko", "t": "Just Solar.", "f": "neutral"}, {"n": "He said it before she could, and she turned to look at him, and he was looking at the floor, like he hadn't meant to say it out loud."}]}]},
    {"n": "Junpei had finished the chips. He folded the bag into a very small square, set it on the arm of the chair, and raised his hand like they were in class."},
    {"s": "junpei", "t": "Can I ask a question? Like, a real one?", "f": "neutral"},
    {"s": "junpei", "t": "What *is* all this? You guys have guns. There's a tower. Everybody's a coffin. What are you, like, a club?", "f": "serious"},
    {"s": "mitsuru", "t": "We're the Specialized Extracurricular Execution Squad.", "f": "neutral"},
    {"s": "junpei", "t": "EXECUTION?!", "f": "surprised"},
    {"s": "yukari", "t": "It's an acronym. S.E.E.S. It sounds worse than it is.", "f": "neutral"},
    {"s": "yukari", "t": "...Okay, it's about as bad as it sounds.", "f": "serious"},
    {"music": "joy"},
    {"n": "Solar laughed. She hadn't meant to. It came up out of her short and surprised, and everyone in the room turned to look at her, and she put her hand over her mouth, and above her hand her face did something she couldn't control at all, and for a second the lounge was warm."},
    {"n": "Mitsuru closed the black case. She left both number fours on the table, side by side."},
    {"s": "mitsuru", "t": "It's late. We'll speak to the Chairman in the morning. In the meantime, you'll stay here.", "f": "neutral"},
    {"s": "mitsuru", "t": "There's a room upstairs. At the end of the girls' hall. It's been made up.", "f": "neutral"},
    {"s": "solar", "t": "For who?"},
    {"n": "Mitsuru looked at her for a long moment, and there was something underneath the composure that Solar would only later recognize as the expression of a very tidy person looking at a single thing that wasn't where she'd left it."},
    {"s": "mitsuru", "t": "I was going to ask you that.", "f": "neutral"},
    {"place": "Iwatodai Dorm · Solar's Room", "time": "2:40 AM", "bg": "solar-dormroom-night", "music": "tender", "date": "4/7"},
    {"n": "Yukari walked her up, because someone had to and Yukari said *fine, I'll do it* before anyone could ask, and then talked the whole way to make up for it. The bathroom's the second door. Don't use the shower after eleven, the pipes scream. Mitsuru-senpai doesn't sleep, so don't be weird about it if you see her at like four in the morning, she's just like that. Akihiko-senpai runs at five. Don't let him make you go. He'll try."},
    {"n": "The room at the end of the hall was small and clean. A bed with fresh sheets, turned down at one corner. A desk and a lamp. Curtains drawn. A wardrobe, and in the wardrobe, when Yukari opened it to show her where the spare blankets were, a second Gekkoukan uniform on a hanger, pressed, in what was obviously her size."},
    {"n": "They both looked at it."},
    {"s": "yukari", "t": "...Huh. That's... convenient.", "f": "neutral"},
    {"s": "yukari", "t": "Okay, that's actually kind of creepy. Sorry. I'm not trying to freak you out.", "f": "serious"},
    {"choose": [{"t": "You're not. I was already freaked out.", "then": [{"s": "yukari", "t": "Ha. Yeah. Fair.", "f": "blushing"}]}, {"t": "Maybe the last transfer forgot it.", "then": [{"s": "yukari", "t": "The last transfer was a guy. Like, two years ago.", "f": "neutral"}, {"s": "yukari", "t": "...Never mind. You're right. Somebody forgot it.", "f": "neutral"}]}, {"t": "Thank you for walking me up.", "then": [{"n": "Yukari looked surprised, the way people do when they've braced for something hard and gotten something soft instead."}, {"s": "yukari", "t": "It's fine. Seriously. It's like four doors.", "f": "blushing"}]}]},
    {"n": "There was a small plate beside the door, at eye level, for a name. It was blank. Yukari's eyes went to it at the same time Solar's did, and away again, quickly, and she did her a kindness by saying nothing."},
    {"s": "yukari", "t": "I'm two doors down. If anything weird happens. Weirder. Just knock.", "f": "neutral"},
    {"n": "The door shut. The room hummed with the particular silence of a building full of sleeping people."},
    {"n": "Solar sat on the edge of the bed in someone else's uniform and put the gun on the desk and looked at it, and then turned the lamp off, and lay down on top of the covers with her shoes still on and her hands folded on her stomach like someone laid out, and stared at the ceiling."},
    {"n": "The shaking started then. Not before. Her hands first, and then her jaw, a fine hard tremor that went all the way down into her knees, and she lay there and let it, very quietly, with the door shut, and the strangest part, the part that kept her awake long after it stopped, was that it felt familiar. That she seemed to know, the way she knew to count the exits, that this was how she did it. That she had always waited until she was alone."},
    {"n": "She shrugged it off. Like, she was fairly sure, she always did."},
    {"place": "The Velvet Room", "time": "", "bg": "velvetroom-elevator", "music": "velvet", "date": "4/7"},
    {"n": "She didn't remember falling asleep. She remembered the ceiling, and the hum of the building, and then she was sitting somewhere soft with her shoes on, and everything was blue."},
    {"n": "It was a deep, rich, impossible blue, like the inside of a closed eye, the walls and the light and the long velvet seat she was sitting on, and the room hummed too, but differently, a smooth climbing hum, and above a pair of brass doors numbers were lighting one after another, too fast to read. An elevator. Rising past floors that didn't belong to any building she'd ever been in, which, she had to admit, was a short list."},
    {"n": "Across from her, standing very straight with a heavy book held against her chest, was a young woman in a blue dress and a little blue cap, with pale hair and golden eyes and the composed, faintly delighted look of someone who had been waiting a long time for a guest and found the guest more interesting than expected."},
    {"s": "elizabeth", "t": "Welcome to the Velvet Room.", "f": "happy"},
    {"s": "elizabeth", "t": "My master is away at present, so I shall be attending to you myself. My name is Elizabeth.", "f": "neutral"},
    {"register": "elizabeth", "quiet": true},
    {"choose": [{"t": "Am I dreaming?", "then": [{"s": "elizabeth", "t": "In a manner of speaking. Though I would advise against assuming that what happens here does not count.", "f": "neutral"}]}, {"t": "Is this Tartarus too?", "then": [{"s": "elizabeth", "t": "Goodness, no. Tartarus is a tower. This is an elevator. They are entirely different. One goes up and is terrible, and the other goes up and is lovely.", "f": "happy"}]}, {"t": "(Stay quiet and watch her.)", "then": [{"n": "Elizabeth watched her back, with frank, bright curiosity, the way a person looks at a new kind of flower."}, {"s": "elizabeth", "t": "Ah. A guest who observes before she speaks. How refreshing.", "f": "happy"}]}]},
    {"s": "elizabeth", "t": "This place exists between dream and reality, mind and matter. Only those who have signed a contract may enter.", "f": "neutral"},
    {"s": "solar", "t": "I haven't signed anything."},
    {"s": "elizabeth", "t": "No. You haven't. Which is the first curious thing about you, of what I suspect will be a great many.", "f": "happy"},
    {"n": "She produced, from somewhere, a single sheet of heavy cream paper and a pen, and held them out. There were only a few lines on the paper, in an old-fashioned hand."},
    {"n": "*I chooseth this fate of mine own free will.*"},
    {"n": "Solar read it twice. She got to *free will* and stopped, and something in her went very still and very hard, the way a jaw sets, at the idea of anyone writing down for her what she had chosen. She didn't know where it came from. It felt like a door in a house she couldn't remember, one she knew she'd slammed many times."},
    {"choose": [{"t": "(Sign it.)", "then": [{"n": "She signed it. Her hand wrote *Solar*, and paused, and the pen hovered where a surname should go, and stayed hovering, and then lifted. That was all she had. She handed it back."}]}, {"t": "What happens if I don't?", "then": [{"s": "elizabeth", "t": "Then you wake up in a small room in a dormitory with a borrowed uniform and a gun on the desk, and nothing that happens to you will be your choice.", "f": "neutral"}, {"s": "elizabeth", "t": "Which I gather is roughly where you already are. So.", "f": "happy"}, {"n": "Solar looked at her. Elizabeth looked back, perfectly pleasant. Solar signed it. Her hand wrote *Solar*, and stopped where a surname should go, and stayed stopped."}]}, {"t": "Who wrote this?", "then": [{"s": "elizabeth", "t": "Someone who believed very much in the idea. You may disagree with it in the margins, if you like. Many guests do.", "f": "neutral"}, {"n": "She signed it. Her hand wrote *Solar*, and stopped where a surname should go, and stayed stopped. She didn't disagree with it in the margins. She thought about it."}]}]},
    {"s": "elizabeth", "t": "Solar. Lovely. The contract is satisfied.", "f": "happy"},
    {"s": "elizabeth", "t": "Now. I keep a book.", "f": "neutral"},
    {"bg": "velvetroom-1"},
    {"n": "She opened the book in her arms. It was enormous and old and bound in blue, and the pages turned under her gloved fingers with a sound like a deck of cards being shuffled by someone who was very good at it. Solar caught glimpses as they went past. Faces in ink, names, small careful paragraphs, and on some pages a little drawing of a figure in armor or a mask or a gown."},
    {"s": "elizabeth", "t": "Everyone who enters this world has a page. It writes itself the moment they arrive, in its own time. Their name, where they are from, what they carry, what they have left behind. I have never once had to write one myself. It is the most reliable book I own.", "f": "neutral"},
    {"n": "She found the page she wanted, and smiled, and turned the book around to show her."},
    {"cg": "prologue-elizabeth-blank-page"},
    {"n": "The page was blank."},
    {"n": "Not empty the way a new notebook is empty. Blank the way a face is blank, deliberately, with nothing in it on purpose. There was a border around it like the other pages had, fine blue lines, a little flourish at the corners. Inside the border there was nothing. Not a name. Not a mark."},
    {"n": "Elizabeth's smile stayed on for a second longer than it meant to, and then it went away, and what was left behind was something Solar didn't expect at all. It wasn't performance or delight. It was a real, plain confusion, the face of a person looking down at something in her own house that she has never seen before."},
    {"s": "elizabeth", "t": "...Oh.", "f": "serious"},
    {"n": "She turned the book back around and looked at it herself. She held it up toward the light from the ceiling and tilted it, as if something might be hiding in the grain of the paper. She turned the page over and looked at the back of it. Nothing. She turned it back. She took a fountain pen from the air, or from her sleeve, and touched the nib to the paper and wrote, carefully, *S*. The ink sat on the page for a moment like a drop of rain on a window. Then it beaded, and ran, and slid off the bottom edge of the page entirely, and was gone, and the paper underneath it was perfectly dry."},
    {"s": "elizabeth", "t": "I have never seen that before.", "f": "serious"},
    {"choose": [{"t": "Is that bad?", "then": [{"s": "elizabeth", "t": "I don't know.", "f": "neutral"}, {"n": "She said it simply, without decoration. Then she looked up from the page, and her golden eyes were wide and bright."}, {"s": "elizabeth", "t": "Isn't that wonderful? I so rarely don't know things.", "f": "happy"}]}, {"t": "Maybe I'm not supposed to be here.", "then": [{"s": "elizabeth", "t": "Everyone is supposed to be somewhere. The book would know where. It always knows.", "f": "neutral"}, {"s": "elizabeth", "t": "It appears it does not know you.", "f": "serious"}]}, {"t": "Can I try?", "then": [{"n": "Elizabeth held the pen out without a word. Solar took it and wrote her own name, the only part of it she had. The ink slid off like the first time. Elizabeth watched it go with an expression of intense, almost scientific interest."}, {"s": "elizabeth", "t": "Not even from you. How extraordinary.", "f": "neutral"}]}]},
    {"cg": null},
    {"s": "elizabeth", "t": "There is one page, at least, that is not blank.", "f": "neutral"},
    {"n": "She turned to the back of the book, where the pages were different, thicker and older, and each one held a single figure drawn in ink and color. She found the one she wanted and held it out, and it was the woman from the corridor, the pink and gold, the crown, the veil with a sun behind it, the rope."},
    {"s": "elizabeth", "t": "Your Persona. The self you summon. She is written, though I must say her name will not sit still on the page either.", "f": "neutral"},
    {"n": "It wouldn't. Solar watched the letters under the drawing shiver and rearrange like water reflecting something that kept moving."},
    {"s": "elizabeth", "t": "I believe she is called Haenim. Lady Sun. There is a story about her. Would you like to hear it?", "f": "happy"},
    {"choose": [{"t": "Yes.", "then": [{"n": "Elizabeth looked very pleased, the way she would always look, Solar would learn, at being asked for a story."}]}, {"t": "Do I have a choice?", "then": [{"s": "elizabeth", "t": "Always. You signed something about it.", "f": "happy"}, {"n": "Solar almost smiled. Elizabeth took it as a yes."}]}]},
    {"s": "elizabeth", "t": "Once, a mother was walking home over the mountains with rice cakes for her children, and a tiger stopped her on the road and said, give me a rice cake and I won't eat you. She gave him one. He stopped her again over the next hill, and the next, until she had no rice cakes left, and then he ate her anyway, and put on her clothes, and went to the house where her children were waiting.", "f": "neutral"},
    {"s": "elizabeth", "t": "The children saw his paws under the door and ran. They climbed a tree in the yard, and the tiger came after them, and at the very top they had nowhere left to go, so they prayed. And heaven let down a rope. A good strong rope, golden in some tellings. The children climbed up it into the sky. The tiger prayed too, and was given a rotten one, and fell.", "f": "neutral"},
    {"s": "elizabeth", "t": "In the sky, the brother was meant to become the sun and the sister the moon. But the sister was frightened of the dark, and frightened of being alone in it, so they traded. And then she found she was frightened of something else.", "f": "neutral"},
    {"s": "elizabeth", "t": "Of people. Looking up at her. Every face in the world, turned toward her, all day.", "f": "serious"},
    {"s": "elizabeth", "t": "So she made herself so bright that no one could look at her directly. She hid by shining. She is still up there doing it.", "f": "neutral"},
    {"n": "Solar sat very still on the velvet seat. She didn't know why her throat had gone tight. It was a children's story, about a tiger and some rice cakes."},
    {"s": "elizabeth", "t": "And her brother became the moon, of course. Someone has to.", "f": "neutral"},
    {"n": "Elizabeth closed the book. The numbers above the doors were slowing."},
    {"s": "elizabeth", "t": "I find I have a great many questions about you, Solar, and you have no answers to give me, which makes us a very well-matched pair. I shall keep your page. If anything ever appears on it, you will be the first to know.", "f": "neutral"},
    {"s": "elizabeth", "t": "I suspect I will be the second. You will be the first.", "f": "happy"},
    {"n": "The light went white at the edges. The last thing she saw was Elizabeth with the blue book held against her chest, lifting one gloved hand in a small formal wave, like a girl seeing someone off at a train station."},
    {"place": "Iwatodai Dorm", "time": "Morning", "bg": "solar-dormroom-day", "music": "school", "date": "4/7"},
    {"n": "She woke at eleven-forty with her shoes still on and sunlight coming through the gap in the curtains in one long bar across the floor, and for a few seconds she didn't know where she was, which, she thought, was at least consistent."},
    {"n": "The dorm was empty. A note on the desk in neat, angled handwriting said *Rest. Do not leave the building. The Chairman will come at four. M.K.* and under it, in a different hand, round and quick, *theres toast stuff in the kitchen!! dont eat junpeis pudding he WILL notice. —Y*"},
    {"n": "In the bathroom mirror, there was a girl. Long black hair, a little tangled. A pale face, fine-boned, the kind people looked at and assumed would break. Dark eyes with something tired behind them that sleep didn't touch. She looked at the girl for a long time, and the girl looked back, and Solar had the strange, seasick feeling of recognizing someone across a room and not being able to place where from."},
    {"n": "Her hands, while she wasn't paying attention, gathered her hair at the back of her head, twisted it, and pinned it up, neat and tight and quick, in a way that did not let a single strand fall, the way you'd fix your hair before you walked into a room full of people who were going to look at you."},
    {"n": "She looked at it in the mirror. It looked good. It looked like someone else's rule."},
    {"choose": [{"t": "(Leave it up.)", "then": [{"n": "She left it. It felt like armor, and she wasn't sure yet that she didn't need some."}], "flag": {"pro-hair-up": true}}, {"t": "(Take it down.)", "then": [{"n": "She took it down. It fell around her shoulders, and the girl in the mirror looked a little younger and a lot more tired, and a little more like someone Solar might have been able to talk to."}]}]},
    {"bg": "iwatodaidorm-kitchen"},
    {"n": "In the kitchen she opened every cupboard, one after another, looking for something, and didn't find it, and couldn't have said what it was. Something sweet in a can. Something cold. She stood there with the last cupboard open, looking at a jar of instant coffee and a box of green tea with the feeling of a word on the tip of her tongue, and then she gave up and made toast, and didn't eat Junpei's pudding, and washed the plate afterward, and the mug, and dried both, and put them back exactly where she'd found them. Like she was a guest. Like she was used to not leaving traces."},
    {"n": "She didn't notice she was humming until Yukari came home at half past three and stopped in the kitchen doorway with her bag still on her shoulder."},
    {"s": "yukari", "t": "What's that song?", "f": "neutral"},
    {"n": "Solar stopped. She hadn't known she was doing it. The tune was still in her mouth, a few bars of something low and unfinished, the kind of melody that sounds like it was written at three in the morning by someone who didn't want anyone to hear it, and it went somewhere and then stopped, the way a song stops when its maker hasn't decided how it ends."},
    {"choose": [{"t": "I don't know.", "then": [{"s": "yukari", "t": "Huh. Is it from a drama? It sounds like a drama. Like the part where somebody's standing in the rain.", "f": "neutral"}]}, {"t": "I didn't know I was humming.", "then": [{"s": "yukari", "t": "You were, like, really going for it.", "f": "neutral"}, {"s": "yukari", "t": "It's nice. Kind of sad. Is it from a drama?", "f": "blushing"}]}, {"t": "(Hum the next part.)", "then": [{"n": "She hummed the next part, to see if she could, and she could. She knew every note of it and not one word. There might not have been words. Yukari tilted her head."}, {"s": "yukari", "t": "Is it from a drama? I feel like I'd know it.", "f": "neutral"}]}]},
    {"n": "Solar didn't know. Yukari, who knew every song on every chart because she was the kind of girl who made it her business to, didn't either."},
    {"place": "Iwatodai Dorm · Lounge", "time": "4:00 PM", "bg": "iwatodaidorm-livingroom", "music": "school", "date": "4/7"},
    {"n": "The Chairman was a thin man in a brown suit with round glasses and long hair tied back and a smile that arrived in the room a full second before the rest of him. He sat down across from her with a manila folder, and Mitsuru stood at his shoulder, and Akihiko leaned on the counter pretending to read a sports magazine, and Junpei had been sent home."},
    {"s": "ikutsuki", "t": "Shuji Ikutsuki. Chairman of the board at Gekkoukan, and of this little household. Welcome. Or should I say, welcome *back*? No, no, I shouldn't, should I. Sorry. I'm told I'm not very good at first impressions."},
    {"s": "mitsuru", "t": "Chairman.", "f": "neutral"},
    {"s": "ikutsuki", "t": "Yes, yes. To business."},
    {"n": "He opened the folder on the coffee table and turned it so she could read it."},
    {"n": "It was a Gekkoukan enrollment form, the official kind, stamped in two places and signed in a third. Transfer student. Third year. Date of enrollment: April seventh. There was a homeroom assigned to her, and a locker number, and a student ID number. In the space for her photo, there was a photo. It was her. Hair down. Not smiling. She didn't remember it being taken."},
    {"n": "Where it said *given name* it said *Solar*. Where it said *family name* there was nothing at all. Not a blank someone had forgotten to fill. A clean white box with a line under it, waiting."},
    {"s": "ikutsuki", "t": "The school's records have you as a transfer student who began classes this morning. Your homeroom teacher marked you absent today."},
    {"s": "ikutsuki", "t": "So, technically, you've already started skipping class! Ha ha. You're really on a roll."},
    {"n": "No one laughed. Akihiko turned a page of a magazine he wasn't reading. Ikutsuki looked faintly pleased with himself anyway."},
    {"choose": [{"t": "Who filled this in?", "then": [{"s": "ikutsuki", "t": "Well, now, that's the funny thing. It came through the system in March, like any transfer. I signed it myself. I remember signing it. I don't remember there being a photograph."}, {"s": "mitsuru", "t": "Or a missing surname.", "f": "neutral"}, {"s": "ikutsuki", "t": "Or that. No."}]}, {"t": "Can you fill in the surname?", "then": [{"s": "ikutsuki", "t": "Hm. I'd rather we didn't guess. Names are funny things, aren't they? Better to leave it blank until it comes back to you. I'm sure it will."}, {"n": "He smiled. It was a perfectly nice smile. She didn't know why she wanted to count the exits again."}]}, {"t": "That's me in the photo.", "then": [{"s": "ikutsuki", "t": "Very much so. A good likeness, too! Though I suppose you'd know better than I would."}, {"s": "solar", "t": "I wouldn't, actually."}, {"s": "ikutsuki", "t": "...No. I suppose you wouldn't."}]}]},
    {"s": "mitsuru", "t": "For now, you'll attend Gekkoukan. You'll live here. And you'll come with us, at night, if you're willing. We'll talk properly about what that means when you've rested.", "f": "neutral"},
    {"s": "mitsuru", "t": "It isn't an order. I want to be clear about that.", "f": "neutral"},
    {"n": "It was the second time in two days somebody had told her that what happened next was her choice, and it was the first time she believed it. She looked up at Mitsuru, surprised, and Mitsuru held her eyes and didn't look away."},
    {"n": "On the way upstairs, Akihiko fell into step beside her without saying anything, the magazine rolled in one hand."},
    {"s": "akihiko", "t": "Do you run?", "f": "neutral"},
    {"s": "solar", "t": "I don't know."},
    {"s": "akihiko", "t": "Tomorrow, then. Five. We'll find out.", "f": "happy"},
    {"s": "solar", "t": "Yukari told me not to let you make me."},
    {"s": "akihiko", "t": "Yukari's not wrong.", "f": "neutral"},
    {"s": "akihiko", "t": "Five, though.", "f": "happy"},
    {"place": "Iwatodai Dorm · Solar's Room", "time": "11:59 PM", "bg": "solar-dormroom-night", "music": "night", "date": "4/7"},
    {"n": "She couldn't sleep, so she didn't try. She sat on the windowsill in someone else's pajamas with her knees up and her forehead against the glass, and watched the street, and waited for midnight, because she wanted to see it happen, and she wanted to see it happen on her own."},
    {"dark": true},
    {"n": "It came with no warning at all. One second the streetlights were orange and a car was turning at the corner, and the next the car was gone and the light was green and the moon above the station was huge and swollen and the wrong color, nearly full, a night or two from round. Along the sidewalk below, three people who had been walking home were coffins. A cat sat on a wall and didn't become anything, and looked up at her window, and looked away."},
    {"n": "It was very quiet. It was quiet the way the corridor had been quiet, a held breath of a quiet, and she sat in it with her forehead on the cold glass and found that she didn't hate it, which was its own kind of worrying."},
    {"n": "Then, from very far off, from somewhere past the station, past the dark shapes of the buildings toward the water, came a sound she knew immediately and could not account for at all."},
    {"n": "A train's horn. Long, and low, and in no hurry. The sound a train makes at the end of a long line, going somewhere that isn't on any timetable."},
    {"n": "Mitsuru had said nothing ran in the Dark Hour. No trains. No cars. Nothing."},
    {"dark": false},
    {"n": "The horn sounded once, and stopped, and didn't come again. Solar sat at the window until the green drained out of the sky and the streetlights came back on, orange and ordinary, and a car came round the corner, and someone below picked up a conversation in the middle of a sentence."},
    {"n": "She thought about the girl in the coat at the end of the corridor, who had been sorry she was awake. She hadn't told anyone else about her. She didn't know why. It felt like the girl's to tell."},
    {"place": "Iwatodai Station · Monorail", "time": "Morning", "bg": "subway-populated", "music": "school", "date": "4/8"},
    {"n": "Akihiko had been waiting at the bottom of the stairs at five. She had gone. She had found out. She did run, apparently, and she was a good deal better at it than either of them expected, and worse at stopping, and when they got back to the dorm at six he had looked at her bent double on the front step and said *not bad* with the satisfied, faraway look of a man who has just found a new hobby, and she had been too out of breath to tell him that she was not going to be one."},
    {"n": "Yukari walked her to school, because someone had to, and Yukari said *fine, I'll do it* before anyone could ask."},
    {"n": "The monorail ran out across the bay in a long white curve with the city falling away behind it, and the morning came in off the water bright and cold and smelling faintly of salt, and Solar stood at the window holding a strap with the borrowed bag over her shoulder and watched Port Island come toward them across the water, its towers and its trees and, at the edge of it, low and pale among the green, a school."},
    {"s": "yukari", "t": "So. Gekkoukan. It's actually a pretty good school. The cafeteria's terrible, and the vice principal is a nightmare, but don't tell anyone I said that.", "f": "neutral"},
    {"s": "yukari", "t": "And, um. Just so you know. It's normal during the day. Like, totally normal. You'd never know.", "f": "serious"},
    {"n": "Solar knew what she meant. She didn't say so."},
    {"bg": "outside-school"},
    {"place": "Gekkoukan High · Front Gate", "time": "Morning", "soft": true},
    {"cg": "prologue-first-day-gekkoukan"},
    {"n": "At the gate, the cherry trees were in full bloom, so full they looked unreal, a long avenue of them on both sides of the path, and the wind kept shaking petals loose in slow pink drifts that caught in people's hair and collars and went skating across the paving stones. Students poured in through the gate in their black blazers, talking, yawning, shoving, a boy with a bad haircut running late, two girls sharing one pair of earbuds. The whole place was loud and bright and ordinary and full of sun."},
    {"n": "She stopped just inside the gate and looked up at the building."},
    {"n": "It was a school. Four stories of white and glass, a clock on the front, windows full of morning. She had woken up inside it. At midnight it was a tower that went up into the green until you lost it, and its first floor was a checkerboard of cold tiles with dark puddles on it that she had decided were water, and somewhere in it, at the end of a corridor that bent out of sight, a girl in a coat too big for her had been sorry that she was awake."},
    {"n": "A petal landed on her sleeve. The left one. Where an armband would go."},
    {"n": "Someone behind her yelled *Sanada-senpai!* in a pitch that hurt, and a ripple went through the girls by the shoe lockers, and Akihiko jogged past in his gym clothes with a towel around his neck, having apparently run here too, and nodded at her once on his way by, serious, like they were teammates. A dozen girls turned to look at her with naked, murderous interest."},
    {"cg": null},
    {"s": "yukari", "t": "...Oh, great. Congratulations. You're famous now.", "f": "neutral"},
    {"s": "yukari", "t": "Faculty office is this way. Come on, Just Solar.", "f": "neutral"},
    {"place": "Gekkoukan High · Classroom", "time": "Homeroom", "bg": "gekkoukan-classroom-day", "music": "school", "date": "4/8"},
    {"n": "The teacher was a tired woman with a clipboard who had been informed that morning, by the Chairman personally, that the absent transfer student was not, in fact, absent anymore, and who had decided not to ask any further questions about it before nine a.m. Solar stood at the front of a room full of strangers in uniforms that matched hers and was looked at, and did the thing her body knew how to do, which was lift her chin, and smile, pleasant and closed, the exact amount, the way you smile at a room you need to like you and don't need to know you."},
    {"n": "It came so easily. That was the part she would think about, later. It fit her like the uniform did."},
    {"n": "She took the empty desk by the window. The cherry trees outside were throwing petals at the glass. The teacher ran down her clipboard, calling names, and people answered, *here*, *here*, *present*, *here*, bored and half asleep, a whole room of people who knew exactly who they were and had never had to think about it once."},
    {"n": "The teacher got to the bottom of the list and stopped, and frowned at it, and tilted the clipboard as if a little more light might bring something out."},
    {"s": "teacher", "t": "Solar...?"},
    {"n": "The pause hung there for the space of a breath, where a surname should have been. A few people turned around in their seats to look at the new girl."},
    {"n": "She thought about the tiles, and the gun that had been set down beside her hand, and a room made up for her before she came, and a uniform pressed in her size, and a blank white box with a line under it, waiting. She thought about a book in a blue room with a page in it that wouldn't take ink. She thought about a train somewhere past the station, sounding its horn in the dark for no one."},
    {"n": "She didn't know who she was. Nobody in this room did either. It seemed, for the moment, like a fair place to start."},
    {"s": "solar", "t": "Here."},
    {"n": "She said it because it was the only word in the room she was sure was true."},
    {"act": {"numeral": "I", "title": "the year begins"}}
  ]
};
